// Turns the shared protobuf vectors (tests/parity/fixtures/protobuf-index-scheme-vectors.json)
// into an AssemblyScript module the matchstick tests import. AssemblyScript has
// no filesystem access, so the JSON cannot be read at test time. The output is
// gitignored and regenerated by `npm test`.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const src = join(here, "../../tests/parity/fixtures/protobuf-index-scheme-vectors.json");
const out = join(here, "../tests/vectors.generated.ts");
const data = JSON.parse(readFileSync(src, "utf8"));
const q = (s) => JSON.stringify(s);

let ts = `// GENERATED by scripts/gen-vector-tests.mjs from protobuf-index-scheme-vectors.json. Do not edit.
export class Vector {
  name: string = "";
  hex: string = "";
  counts: boolean = false;
  isTombstone: boolean = false;
  indexScheme: i64 = 0;
  hasId: boolean = false;
  id: string = "";
  hasVersion: boolean = false;
  version: i32 = 0;
  hasFull: boolean = false;
  owner: string = "";
  timestamp: string = "";
  contentFp: string = "";
  blobHex: string = "";
  embedding: string = "";
  decayScore: string = "";
  blindIndices: string[] = [];
}

export function vectors(): Vector[] {
  let all: Vector[] = [];
`;
for (const v of data.vectors) {
  const e = v.expected;
  const full = "owner" in e;
  ts += `  {
    let v = new Vector();
    v.name = ${q(v.name)};
    v.hex = ${q(v.payloadHex)};
    v.counts = ${v.counts};
    v.isTombstone = ${v.isTombstone};
    v.indexScheme = ${e.indexScheme};
`;
  if ("id" in e) ts += `    v.hasId = true; v.id = ${q(e.id)};\n`;
  if ("version" in e) ts += `    v.hasVersion = true; v.version = ${e.version};\n`;
  if (full) {
    ts += `    v.hasFull = true;
    v.owner = ${q(e.owner)}; v.timestamp = ${q(e.timestamp)}; v.contentFp = ${q(e.contentFp)};
    v.blobHex = ${q(e.encryptedBlobHex)}; v.embedding = ${q(e.encryptedEmbedding)};
    v.decayScore = ${q(String(e.decayScore))};
    v.blindIndices = [${e.blindIndices.map(q).join(", ")}];
`;
  }
  ts += `    all.push(v);\n  }\n`;
}
ts += `  return all;\n}\n`;
writeFileSync(out, ts);
console.log(`wrote ${out} (${data.vectors.length} vectors)`);
